def restore_array(n, b):
    a = [0] * n
    for i in range(n):
        if b[i] == 0:
            a[i] = 1
        else:
            a[i] = b[i] + 1

    for i in range(n):
        if a[i] % a[(i + 1) % n] != b[i]:
